 name=s();nd=r('I');shape=[r('Q') for _ in range(nd)];ty=r('I');off=r('Q');print(name,shape,ty,off)
json.dump(meta,open('tools/meta.json','w'))
print('data offset',(f.tell()+31)//32*32)

