const std=@import("std");
const engine=@import("engine.zig");
const Model=engine.Model;const Context=engine.Context;
const alloc=std.heap.c_allocator;
threadlocal var last_error:?[*:0]const u8=null;
fn clear() void {last_error=null;}
fn fail(msg:[*:0]const u8,code:i32) i32 {last_error=msg;return code;}
fn err(e:anyerror) i32 {last_error=@errorName(e);return switch(e){error.OutOfMemory=>-6,error.ContextCapacity=>-2,error.InvalidToken=>-1,else=>-6};}
export fn bonsai_abi_version() u32 {clear();return 1;}
export fn bonsai_last_error() ?[*:0]const u8 {return last_error;}
export fn bonsai_model_open(path:?[*:0]const u8,out:?*?*Model) i32 {clear();if(path==null or out==null)return fail("null model argument",-1);out.?.*=null;const m=Model.open(std.mem.span(path.?)) catch |e|return err(e);out.?.*=m;return 0;}
export fn bonsai_model_close(m:?*Model) void {clear();if(m)|p|p.close();}
