fn hadBatch(self:*Context,x:u64,y:u64,width:u32,inverse:bool,n:u32) void {self.model.dispatch(.hadamard,.{.w=self.model.sign(width),.x=x,.y=y,.a=width,.b=@intFromBool(inverse)},width/512,n);}
fn matBatch(self:*Context,name:[]const u8,x:u64,y:u64,n:u32) !void {const t=try self.model.tensor(name);self.model.dispatch(.matmul,.{.w=self.model.weights.addr+t.offset,.x=x,.y=y,.a=@intCast(t.dims[0]),.b=@intCast(t.dims[1]),.c=t.typ,.d=n},@intCast((t.dims[1]+63)/64),(n+15)/16);}
fn layerMatBatch(self:*Context,l:u32,suffix:[]const u8,x:u64,y:u64,n:u32) !void {var buf:[96]u8=undefined;try self.matBatch(try layerName(&buf,l,suffix),x,y,n);}
fn normBatch(self:*Context,l:u32,suffix:[]const u8,x:u64,y:u64,width:u32,heads:u32,z:u64,n:u32) !void {self.model.dispatch(.norm,.{.w=try self.layerAddr(l,suffix),.x=x,.y=y,.z=z,.a=width,.b=if(z!=0)2 else 0},heads*n,1);}
fn forwardBatch(self:*Context,ids:[]const i32,with_logits:bool) !void {
    const m=self.model;const n:u32=@intCast(ids.len);
    const token_ptr:[*]i32=@ptrCast(@alignCast(self.work.ptr+@as(usize,@intCast(self.argmax-self.work.addr))));@memcpy(token_ptr[0..ids.len],ids);
    m.dispatch(.embed,.{.w=try m.addr("token_embd.weight"),.x=self.argmax,.y=self.tmp,.a=2560,.c=1},10,n);
    self.hadBatch(self.tmp,self.x,2560,true,n);
    var linear:u64=0;var full:u64=0;
    for(0..32) |li| {const l:u32=@intCast(li);
        try self.normBatch(l,"attn_norm.weight",self.x,self.norm,2560,1,0,n);
        self.hadBatch(self.norm,self.trans,2560,false,n);
        if((l+1)%4!=0){
            try self.layerMatBatch(l,"attn_qkv.weight",self.trans,self.qkv,n);
            try self.layerMatBatch(l,"attn_gate.weight",self.trans,self.gate,n);
            try self.layerMatBatch(l,"ssm_alpha.weight",self.norm,self.alpha,n);
            try self.layerMatBatch(l,"ssm_beta.weight",self.norm,self.beta,n);
            m.dispatch(.conv,.{.w=try self.layerAddr(l,"ssm_conv1d.weight"),.x=self.qkv,.y=self.conv,.s=self.conv_state+linear*8192*3*4,.a=n},32,1);
            m.dispatch(.gdn_batch,.{.w=try self.layerAddr(l,"ssm_dt.bias"),.x=self.conv,.y=self.att,.z=try self.layerAddr(l,"ssm_a"),.s=self.gdn_state+linear*32*128*128*4,.t=self.alpha,.u=self.beta,.a=n},64,1);
            try self.normBatch(l,"ssm_norm.weight",self.att,self.tmp,128,32,self.gate,n);
            self.hadBatch(self.tmp,self.trans,4096,false,n);
            try self.layerMatBatch(l,"ssm_out.weight",self.trans,self.down,n);linear+=1;
        }else{
            try self.layerMatBatch(l,"attn_q.weight",self.trans,self.qkv,n);
            try self.layerMatBatch(l,"attn_k.weight",self.trans,self.k,n);
            try self.layerMatBatch(l,"attn_v.weight",self.trans,self.v,n);
            const cache=self.kv+full*2*@as(u64,self.n_ctx)*1024*2;
            m.dispatch(.attprep,.{.w=try self.layerAddr(l,"attn_q_norm.weight"),.x=self.qkv,.y=self.q,.z=self.qgate,.a=self.pos,.b=0},16,n);
            m.dispatch(.attprep,.{.w=try self.layerAddr(l,"attn_k_norm.weight"),.x=self.k,.y=cache,.z=cache+@as(u64,self.n_ctx)*1024*2,.s=self.v,.a=self.pos,.b=1},4,n);
            m.dispatch(.attscore,.{.w=cache,.x=self.q,.y=self.scores,.a=self.pos+1,.b=self.n_ctx},(self.pos+n+3)/4,16*n);
            m.dispatch(.softmax,.{.x=self.scores,.a=self.pos+1,.b=self.n_ctx},16*n,1);
            m.dispatch(.attvalue,.{.w=cache+@as(u64,self.n_ctx)*1024*2,.x=self.scores,.y=self.att,.a=self.pos+1,.b=self.n_ctx},16*n,1);
            self.elem(self.att,self.qgate,self.tmp,4096*n,2);
            self.hadBatch(self.tmp,self.trans,4096,false,n);
            try self.layerMatBatch(l,"attn_output.weight",self.trans,self.down,n);full+=1;
        }
        self.elem(self.x,self.down,self.x,2560*n,0);
        try self.normBatch(l,"post_attention_norm.weight",self.x,self.norm,2560,1,0,n);
        self.hadBatch(self.norm,self.trans,2560,false,n);
        try self.layerMatBatch(l,"ffn_gate.weight",self.trans,self.fg,n);
        try self.layerMatBatch(l,"ffn_up.weight",self.trans,self.fu,n);
        self.elem(self.fg,self.fu,self.mid,9216*n,1);
        self.hadBatch(self.mid,self.trans,9216,false,n);
        try self.layerMatBatch(l,"ffn_down.weight",self.trans,self.down,n);
        self.elem(self.x,self.down,self.x,2560*n,0);
    }
    if(with_logits){const last=self.x+@as(u64,n-1)*2560*4;try self.normOp("output_norm.weight",last,self.norm,2560,1,0);self.had(self.norm,self.trans,2560,false);try self.mat("token_embd.weight",self.trans,self.logits);}
    self.pos+=n;
}

