fn mat(self:*Context,name:[]const u8,x:u64,y:u64) !void {const t=try self.model.tensor(name);self.model.dispatch(if(t.typ==143).matvec_fast else .matvec,.{.w=self.model.weights.addr+t.offset,.x=x,.y=y,.a=@intCast(t.dims[0]),.b=@intCast(t.dims[1]),.c=t.typ},@intCast((t.dims[1]+(if(t.typ==143)@as(u64,15) else 3))/(if(t.typ==143)@as(u64,16) else 4)),1);}
fn normOp(self:*Context,name:[]const u8,x:u64,y:u64,width:u32,heads:u32,z:u64) !void {self.model.dispatch(.norm,.{.w=try self.model.addr(name),.x=x,.y=y,.z=z,.a=width,.b=if(z!=0)2 else 0},heads,1);}
fn elem(self:*Context,x:u64,z:u64,y:u64,n:u32,op:u32) void {self.model.dispatch(.element,.{.x=x,.z=z,.y=y,.a=n,.b=op},(n+255)/256,1);}
fn layerName(buf:[]u8,layer:u32,suffix:[]const u8) ![]const u8 {return std.fmt.bufPrint(buf,"blk.{d}.{s}",.{layer,suffix});}
fn layerMat(self:*Context,layer:u32,suffix:[]const u8,x:u64,y:u64) !void {var buf:[96]u8=undefined;try self.mat(try layerName(&buf,layer,suffix),x,y);}
