    const ptr:[*]const f32=@ptrCast(@alignCast(self.work.ptr+@as(usize,@intCast(address-self.work.addr))));
    std.debug.print("TRACE {s}: {d:.6} {d:.6} {d:.6} ... {d:.6} {d:.6} {d:.6}\n",.{label,ptr[0],ptr[1],ptr[2],ptr[n-3],ptr[n-2],ptr[n-1]});
