}
fn hadBatch(self:*Context,x:u64,y:u64,width:u32,inverse:bool,n:u32) void {self.model.dispatch(.hadamard,.{.w=self.model.sign(width),.x=x,.y=y,.a=width,.b=@intFromBool(inverse)},width/512,n);}
fn matBatch(self:*Context,name:[]const u8,x:u64,y:u64,n:u32) !void {
    const t=try self.model.tensor(name);const width:u32=@intCast(t.dims[0]);const rows:u32=@intCast(t.dims[1]);const count=width*rows;
