const std = @import("std");
const vk = @import("vk.zig");
const c = vk.c;
const gg = @import("model.zig");
const tok = @import("tokenizer.zig");
const shaders = @import("shaders");
const alloc = std.heap.c_allocator;
const batch_size = 256;
pub const Params = extern struct { w: u64 = 0, x: u64 = 0, y: u64 = 0, z: u64 = 0, s: u64 = 0, t: u64 = 0, u: u64 = 0, v: u64 = 0, a: u32 = 0, b: u32 = 0, c: u32 = 0, d: u32 = 0, e: u32 = 0, f: u32 = 0, g: u32 = 0, h: u32 = 0 };
const Op = enum { matvec, hadamard, norm, element, embed, conv, gdn, attprep, attscore, softmax, attvalue, argmax, gdn_batch, matmul, matvec_fast, dequant, cast, matmul_f16, flash, attreduce, dequant_tiled, cast_tiled, matmul_f16_tiled };
pub const Model = struct {
    gguf: gg.Model,
    tokenizer: tok.Tokenizer,
    gpu: vk.Runtime,
    weights: vk.Buffer,
    signs: vk.Buffer,
    pipes: [23]vk.Pipeline,
    n_vocab: u32,

