 else{bytes=uvec4(word&255,(word>>8)&255,word&255,(word>>8)&255);mul=lane==30?uvec4(1,1,3,3):uvec4(9,9,27,27);}
 uvec4 q=((((bytes*mul)&255)*3)>>8)-1;
 return(q.x&255)|((q.y&255)<<8)|((q.z&255)<<16)|((q.w&255)<<24);
}
void main(){uint lane=gl_LocalInvocationID.x%32,row=gl_WorkGroupID.x*16+(gl_LocalInvocationID.x/32)*4;if(row>=p.b)return;vec4 sum=vec4(0);uint blocks=p.a/128;
 uint word_index=lane<20?lane%4:(lane<30?4+(lane-20)%2:6);
 for(uint block=0;block<blocks;block++){
  uvec4 base=(uvec4(row,row+1,row+2,row+3)*blocks+block)*7;
  uvec4 packed=uvec4(trits(I(p.w).d[base.x+word_index],lane),trits(I(p.w).d[base.y+word_index],lane),trits(I(p.w).d[base.z+word_index],lane),trits(I(p.w).d[base.w+word_index],lane));
