    mod.addRPath(.{ .cwd_relative = "/opt/vulkan-sdk/lib/VulkanLoader/lib" });
    mod.linkSystemLibrary("vulkan", .{});
    const lib = b.addLibrary(.{ .name = "bonsai", .linkage = .dynamic, .root_module = mod });
    b.installArtifact(lib);
}

